package com.ercopac.ercopac_tracker.crm.domain;
import com.ercopac.ercopac_tracker.organisation.domain.Organisation; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="crm_report_schedules") public class CrmReportSchedule { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="organisation_id",nullable=false) private Organisation organisation; @Column(nullable=false) private String reportType; @Column(name="type_filter",nullable=false,length=20) private String typeFilter="ALL"; @Column(nullable=false,length=2000) private String recipients; @Column(nullable=false) private String frequency; @Column(nullable=false) private boolean active=true; private LocalDateTime lastSentAt; @Column(nullable=false) private LocalDateTime nextRunAt; public Long getId(){return id;} public Organisation getOrganisation(){return organisation;} public void setOrganisation(Organisation v){organisation=v;} public String getReportType(){return reportType;} public void setReportType(String v){reportType=v;} public String getTypeFilter(){return typeFilter;} public void setTypeFilter(String v){typeFilter=v;} public String getRecipients(){return recipients;} public void setRecipients(String v){recipients=v;} public String getFrequency(){return frequency;} public void setFrequency(String v){frequency=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public LocalDateTime getLastSentAt(){return lastSentAt;} public void setLastSentAt(LocalDateTime v){lastSentAt=v;} public LocalDateTime getNextRunAt(){return nextRunAt;} public void setNextRunAt(LocalDateTime v){nextRunAt=v;} }
